import {sha256} from '../science/pipeline.mjs';
const R=6378137,rad=Math.PI/180;
export const project=(lon,lat)=>[R*lon*rad,R*Math.log(Math.tan(Math.PI/4+lat*rad/2))];
export const unproject=(x,y)=>[x/R/rad,(2*Math.atan(Math.exp(y/R))-Math.PI/2)/rad];
export class TrafficRepository{
  constructor({manifestUrl=new URL('../data/traffic/noaa-ais-2025-v1/manifest.json',import.meta.url),fetcher=(...args)=>fetch(...args),cacheEntries=8}={}){this.url=new URL(manifestUrl,import.meta.url);this.fetcher=fetcher;this.cacheEntries=cacheEntries;this.current=null;this.pending=null;this.cache=new Map();this.inflight=new Map();this.entries=null;this.stats={tileFetches:0,cacheHits:0};}
  open(){if(!this.pending)this.pending=(async()=>{const r=await this.fetcher(this.url,{cache:'no-cache'});if(!r.ok)throw Error('ais_catalog_unavailable');const m=await r.json();if(m.format!=='w-alerter-traffic-grid'||m.version!==1||m.year!==2025||m.grid?.crs!=='EPSG:3857'||m.grid.pixelSizeMeters!==100||m.grid.nodata!==0||m.grid.dtype!=='uint32'||m.tiles?.size!==512||!Array.isArray(m.tiles.entries)||m.tiles.entries.length>2000||!/^[a-f0-9]{64}$/.test(m.source?.sha256||''))throw Error('invalid_ais_manifest');this.entries=new Map(m.tiles.entries.map(e=>[e.x+':'+e.y,e]));if(this.entries.size!==m.tiles.entries.length)throw Error('duplicate_ais_tile');this.current=m;return m;})().catch(e=>{this.pending=null;throw e;});return this.pending;}
  async tile(entry){const m=await this.open(),key=m.revision+':'+entry.x+':'+entry.y;if(this.cache.has(key)){this.stats.cacheHits++;const v=this.cache.get(key);this.cache.delete(key);this.cache.set(key,v);return v;}if(!this.inflight.has(key)){const promise=(async()=>{const url=new URL(entry.file,this.url);url.searchParams.set('revision',m.revision);const r=await this.fetcher(url,{cache:'force-cache'});if(!r.ok)throw Error('ais_asset_unavailable');let b=new Uint8Array(await r.arrayBuffer());if(b[0]===31&&b[1]===139){if(b.length!==entry.bytes||await sha256(b)!==entry.sha256)throw Error('ais_checksum_failed');b=new Uint8Array(await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());}if(b.length!==entry.expandedBytes||await sha256(b)!==entry.expandedSha256)throw Error('ais_checksum_failed');const v=new DataView(b.buffer,b.byteOffset,b.byteLength);if(String.fromCharCode(...b.slice(0,4))!=='WAT1'||v.getUint16(4,true)!==1||v.getUint16(18,true)!==4||v.getUint32(10,true)!==entry.x*512||v.getUint32(14,true)!==entry.y*512||b.length!==24+v.getUint16(6,true)*v.getUint16(8,true)*4)throw Error('invalid_ais_tile');const tile={width:v.getUint16(6,true),height:v.getUint16(8,true),columnStart:v.getUint32(10,true),rowStart:v.getUint32(14,true),view:v};this.stats.tileFetches++;this.cache.set(key,tile);while(this.cache.size>this.cacheEntries)this.cache.delete(this.cache.keys().next().value);return tile;})().finally(()=>this.inflight.delete(key));this.inflight.set(key,promise);}return this.inflight.get(key);}
  async getCell(lat,lon){const m=await this.open(),g=m.grid,[x,y]=project(lon,lat),column=Math.floor((x-g.originX)/g.pixelSizeMeters),row=Math.floor((g.originY-y)/g.pixelSizeMeters);if(!Number.isFinite(column)||!Number.isFinite(row)||column<0||column>=g.width||row<0||row>=g.height)return {status:'outside_source_region',value:null,gridCell:null};const w=m.distribution,[centerLon,centerLat]=unproject(g.originX+(column+.5)*100,g.originY-(row+.5)*100),gridCell={column,row,latitude:centerLat,longitude:centerLon,crs:g.crs,projectedCellSizeMeters:100,method:'original source pixel containing projected coordinate; no interpolation'};if(column<w.columnStart||column>=w.columnEnd||row<w.rowStart||row>=w.rowEnd)return {status:'outside_distributed_region',value:null,gridCell};const entry=this.entries.get(Math.floor(column/512)+':'+Math.floor(row/512));if(!entry)return {status:'masked',reason:'source_nodata_not_zero_traffic',value:null,gridCell};const tile=await this.tile(entry),value=tile.view.getUint32(24+((row-tile.rowStart)*tile.width+column-tile.columnStart)*4,true);return value===0?{status:'masked',reason:'source_nodata_not_zero_traffic',value:null,gridCell}:{status:'available',value,gridCell};}
  clearCache(){this.cache.clear();}
}
